p = Path('src/plan.ts')
s = p.read_text().replace('return resources.filter((r) => branchOf(r) === branch);', '''// Stack membership also covers provisioner-created resources without branch tags.
  return resources.filter((r) => branchOf(r) === branch || r.stack_id === `stk-${branch}`);''')
s = s.replace('''  // TODO(INFRA-733): deletes are issued in listing order; the API rejects deleting a resource
  // that others still depend on.
  return [...selected];''', '''  const byId = new Map(selected.map((r) => [r.id, r]));
  const dependents = new Map(selected.map((r) => [r.id, 0]));
  for (const r of selected) {
    for (const id of new Set(r.depends_on ?? [])) {
      if (byId.has(id)) dependents.set(id, dependents.get(id)! + 1);
    }
  }

  // Start with resources that nothing in the selection depends on. Removing one
  // releases its prerequisites, rather than trusting the API's listing order.
  const ready = selected.filter((r) => dependents.get(r.id) === 0);
  const ordered: Resource[] = [];
  for (let i = 0; i < ready.length; i++) {
    const r = ready[i];
    ordered.push(r);
    for (const id of new Set(r.depends_on ?? [])) {
      const dependency = byId.get(id);
      if (!dependency) continue;
      const remaining = dependents.get(id)! - 1;
      dependents.set(id, remaining);
      if (remaining === 0) ready.push(dependency);
    }
  }
  if (ordered.length !== selected.length) {
    throw new Error("cannot plan teardown: dependency cycle among " +
      selected.filter((r) => dependents.get(r.id)! > 0).map((r) => r.id).join(", "));
  }
  return ordered;''')
p.write_text(s)
