test("branch selection is exact and does not follow dependencies into other stacks", () => {
  const resources = [
    res("app", "instance", "feat-a", ["shared"]),
    res("boot", "volume", null, [], "stk-feat-a"),
    res("shared", "volume", null),
    res("other", "volume", null, [], "stk-feat-ab"),
    res("other-tag", "volume", "feat-ab"),
  ];
  assert.deepEqual(buildPlan(resources, "feat-a").steps.map((s) => s.id).sort(), ["app", "boot"]);
  assert.deepEqual(buildPlan(resources, "missing"), { branch: "missing", steps: [], blocked: [] });
});

test("deletion ordering handles shuffled resources, shared dependencies and disconnected nodes", () => {
  const resources = [
    res("volume", "volume", null, [], "stk-feat-a"),
    res("dns", "dns_record", "feat-a", ["lb"]),
    res("network", "network", "feat-a"),
    res("app", "instance", "feat-a", ["subnet", "volume", "shared-outside"]),
    res("snapshot", "snapshot", "feat-a", ["volume"]),
    res("subnet", "subnet", "feat-a", ["network"]),
    res("lb", "load_balancer", "feat-a", ["app", "subnet"]),
    res("bucket", "bucket", "feat-a"),
  ];
  for (const input of [resources, [...resources].reverse()]) {
    const order = buildPlan(input, "feat-a").steps.map((s) => s.id);
    assert.equal(new Set(order).size, resources.length);
    for (const r of resources) {
      for (const dependency of r.depends_on) {
        if (order.includes(dependency)) {
          assert.ok(order.indexOf(r.id) < order.indexOf(dependency), `${r.id} must precede ${dependency}: ${order}`);
        }
      }
    }
  }
});

test("outside dependents block teardown without being pulled into the plan", () => {
  const resources = [
    res("volume", "volume", null, [], "stk-feat-a"),
    res("other-app", "instance", "feat-b", ["volume"], "stk-feat-b"),
  ];
  const plan = buildPlan(resources, "feat-a");
  assert.deepEqual(plan.steps.map((s) => s.id), ["volume"]);
  assert.deepEqual(plan.blocked, [{ id: "volume", dependents: ["other-app"] }]);
});

test("dependency cycles fail planning before any deletion", () => {
  assert.throws(() => buildPlan([
    res("a", "instance", "feat-a", ["b"]),
    res("b", "instance", "feat-a", ["a"]),
  ], "feat-a"), /dependency cycle/);
  assert.throws(() => buildPlan([res("self", "instance", "feat-a", ["self"])], "feat-a"), /dependency cycle/);
});
